// Pure zkFetch test helpers with zero runtime dependencies on Reclaim or
// `@txpipe/thoth-*`. Witness signing accepts the caller's Reclaim primitives.

/** A single regex disclosure match generated by {@link disclosureRules}. */
export interface RegexDisclosureMatch {
  readonly type: 'regex';
  readonly value: string;
}

/** Whole-response regex disclosure rules with no redactions. */
export interface DisclosureRules {
  responseMatches: RegexDisclosureMatch[];
  responseRedactions: never[];
}

/**
 * Build one whole-response `regex` match, `(?<name>.*)`, for each slot name,
 * with no redactions.
 */
export const disclosureRules = (...names: readonly string[]): DisclosureRules => ({
  responseMatches: names.map((name) => ({ type: 'regex', value: `(?<${name}>.*)` })),
  responseRedactions: [],
});

/** {@link disclosureRules} for the `name` of each slot entry. */
export const disclosureRulesOf = (slots: readonly { readonly name: string }[]): DisclosureRules =>
  disclosureRules(...slots.map(({ name }) => name));

/** What a test witness observes; each field lands in the signed claim data. */
export interface TestWitnessObservation {
  /** Disclosed values, signed as the context's `extractedParameters`. */
  values: Readonly<Record<string, string>>;
  /** Observation time, Unix seconds. */
  timestampS: number;
  /** Provider parameters (url, method, body, ...). */
  parameters: Readonly<Record<string, unknown>>;
  /** Extra signed context fields (e.g. a claim context digest). */
  context?: Readonly<Record<string, unknown>>;
}

/** Canonical signed zkFetch evidence shape returned by {@link TestWitness.sign}. */
export interface TestWitnessEvidence {
  claim: {
    provider: string;
    parameters: string;
    owner: string;
    timestampS: number;
    context: string;
    identifier: string;
    epoch: number;
  };
  signatureHex: string;
  attestorAddress: string;
}

/** A witness backed by a local test key; see {@link createTestWitness}. */
export interface TestWitness {
  /** The witness address the attestor recovers (lowercase `0x` + 40 hex). */
  address: string;
  /** Sign an observation into canonical zkFetch evidence. */
  sign(observation: TestWitnessObservation): Promise<TestWitnessEvidence>;
}

/** Structural subset of `@reclaimprotocol/attestor-core` used by {@link createTestWitness}. */
export interface ReclaimSigningPrimitives {
  readonly SIGNATURES: Readonly<
    Record<
      number | string,
      {
        getPublicKey(privateKey: string): Uint8Array;
        getAddress(publicKey: Uint8Array): string;
        sign(data: Uint8Array, privateKey: string): Uint8Array | Promise<Uint8Array>;
      }
    >
  >;
  readonly SelectedServiceSignatureType: number | string;
  canonicalStringify(value: unknown): string;
  createSignDataForClaim(claim: TestWitnessEvidence['claim']): string;
  getIdentifierFromClaimInfo(info: {
    provider: string;
    parameters: string;
    context: string;
  }): string;
}

/** The requester a test witness records as the claim owner. */
const OWNER = '0x445541beb656e0f2359cae936fda3c404c409194';

/**
 * Build a local secp256k1 test witness using caller-supplied Reclaim signing
 * primitives so offline suites mint canonical zkFetch evidence without pulling
 * Reclaim into `@txpipe/thoth-test-utils`.
 *
 * @param reclaim — `@reclaimprotocol/attestor-core` signing primitives.
 * @param privateKey — `0x`-prefixed 32-byte hex secp256k1 key.
 * @throws if `reclaim.SelectedServiceSignatureType` is absent from `reclaim.SIGNATURES`.
 */
export const createTestWitness = (
  reclaim: ReclaimSigningPrimitives,
  privateKey: string,
): TestWitness => {
  const scheme = reclaim.SIGNATURES[reclaim.SelectedServiceSignatureType];
  if (scheme === undefined) {
    throw new Error(
      `createTestWitness: missing signature scheme ${reclaim.SelectedServiceSignatureType}`,
    );
  }
  const address = scheme.getAddress(scheme.getPublicKey(privateKey));
  return {
    address,
    sign: async (observation: TestWitnessObservation): Promise<TestWitnessEvidence> => {
      const info = {
        provider: 'http',
        parameters: reclaim.canonicalStringify(observation.parameters),
        context: reclaim.canonicalStringify({
          ...observation.context,
          extractedParameters: observation.values,
        }),
      };
      const claim: TestWitnessEvidence['claim'] = {
        ...info,
        owner: OWNER,
        timestampS: observation.timestampS,
        identifier: reclaim.getIdentifierFromClaimInfo(info),
        epoch: 1,
      };
      const signature = await scheme.sign(
        new TextEncoder().encode(reclaim.createSignDataForClaim(claim)),
        privateKey,
      );
      return {
        claim,
        signatureHex: `0x${Buffer.from(signature).toString('hex')}`,
        attestorAddress: address,
      };
    },
  };
};
